// Compute the rates in code, so the numbers in the report never come from the model.
const rows = $('Read the CSV').all().map(i => i.json);
const required = ['campaign', 'send_date', 'audience', 'emails_sent', 'hard_bounces', 'unique_opens', 'unique_clicks', 'unsubscribes'];
const missing = required.filter(c => !(c in (rows[0] ?? {})));
if (!rows.length || missing.length) {
  throw new Error('The CSV is missing columns: ' + (missing.join(', ') || 'no rows found'));
}
const n = v => Number(String(v).replace(/,/g, '')) || 0;
const pct = (a, b) => b ? Math.round(a / b * 1000) / 10 : 0;

const campaigns = rows.map(r => {
  const sent = n(r.emails_sent), bounces = n(r.hard_bounces), opens = n(r.unique_opens), clicks = n(r.unique_clicks), unsubs = n(r.unsubscribes);
  const delivered = sent - bounces;
  const c = {
    campaign: String(r.campaign), send_date: String(r.send_date), audience: String(r.audience),
    sent, delivered,
    open_rate: pct(opens, delivered), click_rate: pct(clicks, delivered), click_to_open: pct(clicks, opens),
    unsubscribe_rate: pct(unsubs, delivered), bounce_rate: pct(bounces, sent),
  };
  const flags = [];
  if (c.bounce_rate > 2) flags.push('bounce rate above 2%: clean the list');
  if (c.unsubscribe_rate > 0.5) flags.push('unsubscribes above 0.5%: check targeting and frequency');
  if (c.open_rate < 20) flags.push('open rate below 20%: test the subject line');
  c.flags = flags.join('; ');
  return c;
});

const sum = k => rows.reduce((t, r) => t + n(r[k]), 0);
const delivered = sum('emails_sent') - sum('hard_bounces');
const totals = {
  campaigns: campaigns.length, sent: sum('emails_sent'), delivered,
  open_rate: pct(sum('unique_opens'), delivered), click_rate: pct(sum('unique_clicks'), delivered),
  unsubscribe_rate: pct(sum('unsubscribes'), delivered),
};
const byClicks = [...campaigns].sort((a, b) => b.click_rate - a.click_rate);

// What the model sees: the same numbers, with rates written as percentages.
const asPct = o => Object.fromEntries(Object.entries(o).map(([k, v]) => [k, k.endsWith('_rate') || k === 'click_to_open' ? v + '%' : v]));
const forModel = {
  totals: asPct(totals),
  best_by_click_rate: byClicks[0].campaign,
  weakest_by_click_rate: byClicks[byClicks.length - 1].campaign,
  campaigns: campaigns.map(asPct),
};
return [{ json: {
  title: $('Upload campaign export').first().json['Report title'],
  campaigns, totals, forModel,
} }];

