parameters.jsCode:
// Check every number in the commentary against the data, then build the report page.
const m = $('Compute the metrics').first().json;
const out = $input.first().json;
const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));

let ai = null;
try {
  let text = out.candidates?.[0]?.content?.parts?.[0]?.text ?? '';
  text = text.replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/i, '').trim();
  ai = JSON.parse(text);
} catch (e) {
  ai = null;
}

// Every number that may appear: the metrics, the counts, and the digits in names and dates.
const allowed = new Set();
const addNums = v => String(v).match(/\d+(?:\.\d+)?/g)?.forEach(x => allowed.add(String(Number(x))));
Object.values(m.totals).forEach(addNums);
m.campaigns.forEach(c => Object.values(c).forEach(addNums));
[2, 0.5, 20].forEach(addNums);

let commentaryHtml, unverified = [];
if (!ai || !ai.headline) {
  commentaryHtml = '<p><i>No commentary: the model did not answer. The numbers below are complete.</i></p>';
} else {
  const text = [ai.headline, ...(ai.points ?? [])].join(' ');
  unverified = [...new Set((text.replace(/,(?=\d{3})/g, '').match(/\d+(?:\.\d+)?/g) ?? []).map(x => String(Number(x))))]
    .filter(x => !allowed.has(x));
  commentaryHtml = `<p><b>${esc(ai.headline)}</b></p><ul>${(ai.points ?? []).map(p => `<li>${esc(p)}</li>`).join('')}</ul>` +
    (unverified.length
      ? `<p style="color:#b00020"><b>Check before sending:</b> the commentary mentions ${esc(unverified.join(', '))}, which is not in the data.</p>`
      : '<p style="color:#2e7d32">Every number in the commentary matches the data.</p>');
}

const t = m.totals;
const table = `<table border="1" cellpadding="6" style="border-collapse:collapse;font-size:14px">
<tr><th>Campaign</th><th>Sent</th><th>Open</th><th>Click</th><th>Click to open</th><th>Unsub</th><th>Bounce</th><th>Flags</th></tr>
${m.campaigns.map(c => `<tr><td>${esc(c.campaign)}<br><small>${esc(c.send_date)}, ${esc(c.audience)}</small></td><td>${c.sent}</td><td>${c.open_rate}%</td><td>${c.click_rate}%</td><td>${c.click_to_open}%</td><td>${c.unsubscribe_rate}%</td><td>${c.bounce_rate}%</td><td>${esc(c.flags)}</td></tr>`).join('')}
<tr><td><b>All ${t.campaigns}</b></td><td>${t.sent}</td><td>${t.open_rate}%</td><td>${t.click_rate}%</td><td></td><td>${t.unsubscribe_rate}%</td><td></td><td></td></tr></table>`;

const reportHtml = `<h2>${esc(m.title)}</h2>${commentaryHtml}${table}<p>Saved to the campaign_metrics data table.</p>`;
return [{ json: { reportHtml, unverified } }];

// One row per campaign for the data table.
const title = $('Compute the metrics').first().json.title;
return $('Compute the metrics').first().json.campaigns.map(c => ({ json: { report: String(title), ...c } }));
